import {test} from 'node:test';
import assert from 'node:assert/strict';
import {HeartbeatTelemetry} from '../src/mavlink.js';
// Independent wire fixtures generated by pymavlink's ardupilotmega dialect.
const manual=Buffer.from('fe0900010100000000000a038104035d04','hex');
const guided=Buffer.from('fd0900000001010000000f0000000a030104037547','hex');
test('heartbeat decodes v1/v2 arm and Rover modes, invalid data cannot refresh freshness',()=>{
 const t=new HeartbeatTelemetry({systemId:1,timeoutMs:3000});
 assert.equal(t.snapshot(0).connected,false);
 t.receive(manual,100);assert.deepEqual(t.snapshot(100),{connected:true,armed:true,flightMode:'MANUAL',customMode:0,ageMs:0});
 t.receive(guided,200);assert.equal(t.snapshot(200).armed,false);assert.equal(t.snapshot(200).flightMode,'GUIDED');
 const corrupt=Buffer.from(manual);corrupt[8]^=1;t.receive(corrupt,3000);
 t.receive(manual.subarray(0,10),3000);
 assert.equal(t.snapshot(3201).connected,false);assert.equal(t.snapshot(3201).armed,null);
 assert.equal(t.snapshot(3201).flightMode,null);
 t.receive(Buffer.concat([Buffer.from([1,2]),manual,guided]),4000);assert.equal(t.snapshot(4000).flightMode,'GUIDED');
 t.receive(Buffer.from('fd090000000101000000630000000a03810403604e','hex'),4100);
 assert.equal(t.snapshot(4100).flightMode,'MODE 99');
 const other=new HeartbeatTelemetry({systemId:2});other.receive(manual,100);assert.equal(other.snapshot(100).connected,false);
});

// RC fixtures from pymavlink, not the decoder under test.
const rc=Buffer.from('fd2a000000010141000001000000dc05e803dc05d007dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc0508ff021c','hex');
const rawRC=Buffer.from('fe160001012301000000dc05d007dc05e803dc05dc05dc05dc0500ffaafc','hex');
const simstate=Buffer.from('fd2c0000000101a400000000000000000000000000000000000000000000c3f51cc100000000000000000000000098e4001eb01d2a1253ae','hex');
const globalPosition=Buffer.from('fd0f0000000101210000e803000098e4001eb01d2a1260cf026c8f','hex');
test('selected SITL location requires fresh CRC-checked simulation and geographic telemetry',()=>{
 const t=new HeartbeatTelemetry({timeoutMs:3000});assert.equal(t.positionSnapshot(0),null);
 t.receive(simstate,100);assert.equal(t.positionSnapshot(100),null);
 t.receive(globalPosition,200);assert.deepEqual(t.positionSnapshot(200),{lat:50.3375,lon:30.475,alt:184.16});
 const corrupt=Buffer.from(simstate);corrupt[25]^=1;t.receive(corrupt,3100);assert.equal(t.positionSnapshot(3201),null);
 const other=new HeartbeatTelemetry({systemId:2});other.receive(simstate,100);other.receive(globalPosition,100);assert.equal(other.positionSnapshot(100),null);
});
test('RC inputs decode independently of heartbeat, with CRC checks and their own timeout',()=>{
 const t=new HeartbeatTelemetry({timeoutMs:3000});
 assert.equal(t.rcSnapshot(0).connected,false);t.receive(rc,100);
 assert.equal(t.snapshot(100).connected,false);assert.equal(t.rcSnapshot(100).connected,true);
 assert.deepEqual(t.rcSnapshot(100).channels.slice(0,4),[1500,1000,1500,2000]);
 const corrupt=Buffer.from(rc);corrupt[15]^=1;t.receive(corrupt,2000);
 t.receive(manual,3000);assert.equal(t.snapshot(3200).connected,true);assert.equal(t.rcSnapshot(3200).connected,false);
 t.receive(rawRC,4000);assert.deepEqual(t.rcSnapshot(4000).channels.slice(0,4),[1500,2000,1500,1000]);
 const other=new HeartbeatTelemetry({systemId:2});other.receive(rc,100);assert.equal(other.rcSnapshot(100).connected,false);
 const trimmedCentre=Buffer.from('fd29000000010141000002000000dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc05dc0508f6d4','hex');
 t.receive(trimmedCentre,5000);assert.deepEqual(t.rcSnapshot(5000).channels.slice(0,4),[1500,1500,1500,1500]);
});

test('parameter telemetry rejects corrupt values and exposes only current session values',()=>{
 const t=new HeartbeatTelemetry();
 // Independent MAVLink v1 PARAM_VALUE wire layout and checksum fixture.
 const b=Buffer.alloc(33);b.set([254,25,0,1,1,22]);b.writeFloatLE(73,6);b.writeUInt16LE(1,10);b.writeUInt16LE(0,12);b.write('SERVO2_FUNCTION',14);b[30]=9;
 let crc=65535;for(const byte of [...b.subarray(1,31),220]){let x=byte^(crc&255);x^=(x<<4)&255;crc=((crc>>8)^(x<<8)^(x<<3)^(x>>4))&65535;}b.writeUInt16LE(crc,31);
 t.receive(b,0);assert.equal(t.parameterSnapshot().SERVO2_FUNCTION,73);
 const corrupt=Buffer.from(b);corrupt[8]^=1;t.receive(corrupt,5);assert.equal(t.parameterSnapshot().SERVO2_FUNCTION,73);
 t.clearParameters();assert.deepEqual(t.parameterSnapshot(),{});
});
